import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"11. Static Semantics","description":"","frontmatter":{},"headers":[],"relativePath":"spec/11-static-semantics.md","filePath":"spec/11-static-semantics.md","lastUpdated":null}'),r={name:"spec/11-static-semantics.md"};function s(o,e,c,l,d,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="_11-static-semantics" tabindex="-1">11. Static Semantics <a class="header-anchor" href="#_11-static-semantics" aria-label="Permalink to &quot;11. Static Semantics&quot;">​</a></h1><h2 id="_11-1-name-resolution" tabindex="-1">11.1 Name resolution <a class="header-anchor" href="#_11-1-name-resolution" aria-label="Permalink to &quot;11.1 Name resolution&quot;">​</a></h2><p>Every identifier reference MUST resolve unambiguously to a declaration visible in lexical/module scope.</p><p>Unknown and ambiguous names are errors.</p><h2 id="_11-2-definite-declaration" tabindex="-1">11.2 Definite declaration <a class="header-anchor" href="#_11-2-definite-declaration" aria-label="Permalink to &quot;11.2 Definite declaration&quot;">​</a></h2><p>Locals must be declared before use.</p><p><code>var</code> locals must have an initial value; uninitialized locals are not permitted.</p><h2 id="_11-3-return-checking" tabindex="-1">11.3 Return checking <a class="header-anchor" href="#_11-3-return-checking" aria-label="Permalink to &quot;11.3 Return checking&quot;">​</a></h2><p>Every reachable return path in a non-unit function MUST return a value matching the declared return type.</p><p>Implicit return of the final expression is not part of the initial language version. <code>return</code> is explicit.</p><h2 id="_11-4-dtype-equality" tabindex="-1">11.4 Dtype equality <a class="header-anchor" href="#_11-4-dtype-equality" aria-label="Permalink to &quot;11.4 Dtype equality&quot;">​</a></h2><p>Tensor operands for arithmetic operations MUST have identical dtypes after explicit casts and contextual literal typing.</p><p>A backend-specific implicit promotion MUST NOT leak into Linnet semantics.</p><h2 id="_11-5-broadcast-checking" tabindex="-1">11.5 Broadcast checking <a class="header-anchor" href="#_11-5-broadcast-checking" aria-label="Permalink to &quot;11.5 Broadcast checking&quot;">​</a></h2><p>Broadcast relationships MUST be statically provable under the rules in the shape specification.</p><h2 id="_11-6-index-expression-checking" tabindex="-1">11.6 Index-expression checking <a class="header-anchor" href="#_11-6-index-expression-checking" aria-label="Permalink to &quot;11.6 Index-expression checking&quot;">​</a></h2><p>For a tensor comprehension:</p><ul><li>every output index must have a known domain;</li><li>every non-output index used in the expression must be bound by a reduction;</li><li>every reduction index must occur in the reduced expression unless a future explicit-range syntax provides its domain;</li><li>uses of the same index must have compatible domains;</li><li>repeated indices in one tensor imply diagonal selection and require compatible axes.</li></ul><h2 id="_11-7-purity-and-effects" tabindex="-1">11.7 Purity and effects <a class="header-anchor" href="#_11-7-purity-and-effects" aria-label="Permalink to &quot;11.7 Purity and effects&quot;">​</a></h2><p>Initial <code>fn</code>, <code>op</code>, and <code>entry</code> bodies have no hidden effects. Structural composition and local SSA-style reassignment do not count as runtime effects. Reading and assigning <code>state</code> members (§9.3) are effects, and they are explicit: every function&#39;s state footprint is known statically.</p><h2 id="_11-8-recursive-cycles" tabindex="-1">11.8 Recursive cycles <a class="header-anchor" href="#_11-8-recursive-cycles" aria-label="Permalink to &quot;11.8 Recursive cycles&quot;">​</a></h2><p>Direct or indirect recursive calls are errors in the initial language version.</p><h2 id="_11-9-exhaustive-match" tabindex="-1">11.9 Exhaustive match <a class="header-anchor" href="#_11-9-exhaustive-match" aria-label="Permalink to &quot;11.9 Exhaustive match&quot;">​</a></h2><p><code>match</code> over an optional or enum MUST be exhaustive. Duplicate and unreachable arms SHOULD be diagnosed.</p><h2 id="_11-10-compile-time-versus-runtime-values" tabindex="-1">11.10 Compile-time versus runtime values <a class="header-anchor" href="#_11-10-compile-time-versus-runtime-values" aria-label="Permalink to &quot;11.10 Compile-time versus runtime values&quot;">​</a></h2><p>Dimensions, generic shape parameters, block-array lengths, and <code>static for</code> iteration counts are compile-time structural values.</p><p>Runtime tensor contents MUST NOT influence them.</p><p>This separation is required for deterministic static shape checking and portable backend lowering.</p>',28)])])}const m=a(r,[["render",s]]);export{p as __pageData,m as default};
